-- Venda, cancelamento e devolucao atualizam o estoque da variacao.
alter table commerce_sale_items add column if not exists variant_id uuid;
alter table commerce_sale_items add constraint commerce_sale_item_variant_fk foreign key(variant_id,business_id,owner_id) references commerce_product_variants(id,business_id,owner_id);
alter table commerce_sale_return_items add column if not exists variant_id uuid;
alter table commerce_sale_return_items add constraint commerce_return_item_variant_fk foreign key(variant_id,business_id,owner_id) references commerce_product_variants(id,business_id,owner_id);
create function commerce_movimentar_variacao_venda() returns trigger language plpgsql security invoker set search_path=public as $$declare i commerce_sale_items%rowtype;begin if old.status='aberta' and new.status='concluida' then for i in select * from commerce_sale_items where sale_id=new.id and variant_id is not null loop perform 1 from commerce_product_variants where id=i.variant_id and owner_id=new.owner_id and ativo and estoque_atual>=i.quantidade for update;if not found then raise exception 'Estoque insuficiente para a variacao de %.',i.descricao;end if;update commerce_product_variants set estoque_atual=estoque_atual-i.quantidade,updated_at=now() where id=i.variant_id;end loop;elsif old.status='concluida' and new.status='cancelada' then for i in select * from commerce_sale_items where sale_id=new.id and variant_id is not null loop update commerce_product_variants set estoque_atual=estoque_atual+i.quantidade,updated_at=now() where id=i.variant_id;end loop;end if;return new;end;$$;
create trigger commerce_sale_variant_stock before update of status on commerce_sales for each row execute function commerce_movimentar_variacao_venda();
create function commerce_devolver_variacao_venda() returns trigger language plpgsql security invoker set search_path=public as $$declare v uuid;begin select variant_id into v from commerce_sale_items where id=new.sale_item_id and owner_id=new.owner_id;new.variant_id:=v;if v is not null then update commerce_product_variants set estoque_atual=estoque_atual+new.quantidade,updated_at=now() where id=v;end if;return new;end;$$;
create trigger commerce_return_variant_stock before insert on commerce_sale_return_items for each row execute function commerce_devolver_variacao_venda();
